# %%
# Run all questions through both prompt variants
results_v1 = {}
results_v2 = {}

for i, case in enumerate(golden_qa_set[:4]):  # Start with 4 cases to keep tokens low
    q = case["question"]
    print(f"\n[{i+1}/4] {q[:50]}...")
    
