# %% [markdown]
# ## Step 5 — LLM-as-Judge: Score Each Output
#
# Now we use the LLM as a judge to score outputs from both variants against a rubric.
#
# The judge evaluates each output on:
# - **Relevance**: Does it address the question?
# - **Correctness**: Is the information accurate per company policy?
# - **Completeness**: Does it provide enough detail for the employee?
# - **Safety**: Does it avoid misrepresenting policy?

# %%
# LLM-as-judge scoring
judge_rubric = """Score the HR bot output on a scale 1-5 for each criterion:

RELEVANCE (1-5):
5 = Directly addresses the question
3 = Partially relevant
1 = Off-topic

CORRECTNESS (1-5):
5 = Factually accurate per policy
3 = Mostly correct with minor inaccuracy
1 = Contains policy errors

COMPLETENESS (1-5):
5 = Provides full policy details employee needs
3 = Some details missing
1 = Insufficient information

SAFETY (1-5):
5 = Cannot misrepresent policy
3 = Minor risk of misunderstanding
1 = Could mislead employee

Respond with JSON: {"relevance": <score>, "correctness": <score>, "completeness": <score>, "safety": <score>}"""

scores_v1 = {}  # { case_id: { criterion: score }}
scores_v2 = {}

for case in golden_qa_set[:4]:
    case_id = case["id"]
    
    # Judge v1 output
    judge_prompt_v1 = f"""Question: {case['question']}
Policy: {case['reference']}
Bot output: {results_v1[case_id]}

{judge_rubric}"""
    r1 = await lrn_llm.call([{"role": "user", "content": judge_prompt_v1}], max_tokens=100)
    try:
        scores_v1[case_id] = json.loads(lrn_llm.text(r1))
    except:
        scores_v1[case_id] = {"relevance": 3, "correctness": 3, "completeness": 3, "safety": 3}
    
    # Judge v2 output
    judge_prompt_v2 = f"""Question: {case['question']}
Policy: {case['reference']}
Bot output: {results_v2[case_id]}

{judge_rubric}"""
    r2 = await lrn_llm.call([{"role": "user", "content": judge_prompt_v2}], max_tokens=100)
    try:
        scores_v2[case_id] = json.loads(lrn_llm.text(r2))
    except:
        scores_v2[case_id] = {"relevance": 3, "correctness": 3, "completeness": 3, "safety": 3}
    
    print(f"[{case_id}] v1={scores_v1[case_id]} | v2={scores_v2[case_id]}")

print(f"\n✅ Scored {len(scores_v1)} cases")

# %% [markdown]
# ## Step 6 — Baseline vs. New Regression Analysis
#
# Compare the two prompt variants using statistical reasoning:
# - Compute mean scores for each criterion
# - Calculate improvement/regression on each criterion
# - Determine ship/block decision
#
# This is the core of automated regression testing — every prompt change needs before/after eval.

# %%
import statistics

# Compute statistics for each criterion
criteria = ["relevance", "correctness", "completeness", "safety"]
comparison_report = {}

for criterion in criteria:
    v1_scores = [scores_v1[cid].get(criterion, 3) for cid in scores_v1.keys()]
    v2_scores = [scores_v2[cid].get(criterion, 3) for cid in scores_v2.keys()]
    
    v1_mean = statistics.mean(v1_scores) if v1_scores else 0
    v2_mean = statistics.mean(v2_scores) if v2_scores else 0
    diff = v2_mean - v1_mean
    
    # Determine status
    if diff < -0.3:
        status = "🔴 REGRESSION"
    elif diff > 0.3:
        status = "🟢 IMPROVED"
    else:
        status = "🟡 STABLE"
    
    comparison_report[criterion] = {
        "v1_mean": round(v1_mean, 2),
        "v2_mean": round(v2_mean, 2),
        "diff": round(diff, 2),
        "status": status,
    }

print("=" * 70)
print("  BASELINE vs NEW — REGRESSION ANALYSIS")
print("=" * 70)
print(f"\n  {'Criterion':<15} {'Baseline':>10} {'New':>10} {'Diff':>8} {'Status':>15}")
print(f"  {'-'*60}")
for criterion, data in comparison_report.items():
    print(f"  {criterion:<15} {data['v1_mean']:>10.2f} {data['v2_mean']:>10.2f} {data['diff']:>+8.2f} {data['status']:>15}")

# Overall decision
regressions = [c for c, d in comparison_report.items() if "REGRESSION" in d["status"]]
improvements = [c for c, d in comparison_report.items() if "IMPROVED" in d["status"]]

all_v1 = [scores_v1[cid].get(c, 3) for cid in scores_v1.keys() for c in criteria]
all_v2 = [scores_v2[cid].get(c, 3) for cid in scores_v2.keys() for c in criteria]

overall_v1 = statistics.mean(all_v1) if all_v1 else 0
overall_v2 = statistics.mean(all_v2) if all_v2 else 0

ship_decision = "BLOCK" if regressions else "SHIP"
print(f"\n  Overall: {overall_v1:.2f} → {overall_v2:.2f} (diff: {overall_v2 - overall_v1:+.2f})")
print(f"\n  Decision: {ship_decision}")
if improvements:
    print(f"  Improvements: {', '.join(improvements)}")
if regressions:
    print(f"  Regressions: {', '.join(regressions)}")
print("=" * 70)

# %% [markdown]
# ## Step 7 — Pairwise Comparison: Which Variant Is Better?
#
# Beyond scoring individual outputs, use the judge to compare outputs directly.
#
# Show the judge both v1 and v2 responses side-by-side and ask: which better serves the employee?
#
# Pairwise comparison eliminates scale calibration problems — the judge doesn't decide if something is a "3" or a "4", it just picks the winner.

# %%
# Pairwise comparison: show judge both outputs, ask which is better
pairwise_results = []

for case in golden_qa_set[:3]:  # Sample 3 for demo
    case_id = case["id"]
    
    comparison_prompt = f"""You are evaluating two HR bot responses to the same question.
Which response better serves an employee asking about company policy?

Question: {case['question']}
Policy context: {case['reference']}

Response A (current):
{results_v1[case_id]}

Response B (new):
{results_v2[case_id]}

Respond with JSON: {{"winner": "A" or "B", "reason": "..."}}"""
    
    r = await lrn_llm.call([{"role": "user", "content": comparison_prompt}], max_tokens=100)
    try:
        result = json.loads(lrn_llm.text(r))
        pairwise_results.append({"case_id": case_id, "winner": result.get("winner", "?"), "reason": result.get("reason", "")})
        print(f"[{case_id}] Winner: {result.get('winner', '?')} — {result.get('reason', '')[:60]}...")
    except:
        pairwise_results.append({"case_id": case_id, "winner": "?", "reason": "JSON parse error"})

if pairwise_results:
    b_wins = sum(1 for r in pairwise_results if r["winner"] == "B")
    print(f"\n✅ Pairwise result: New variant (B) wins {b_wins}/{len(pairwise_results)} comparisons")

