print(f"\n📊 Regression Analysis:")
if regressions:
    print(f"   ⚠️  Regressions detected: {', '.join(regressions)}")
    print(f"   → BLOCK deployment")
elif improvements:
    print(f"   ✅ Improvements on: {', '.join(improvements)}")
    print(f"   ✅ No regressions detected")
    print(f"   → SHIP deployment")
else:
    print(f"   🟡 Stable performance (no significant change)")
    print(f"   → SHIP if other metrics satisfy requirements")

if pairwise_results:
    b_wins = sum(1 for r in pairwise_results if r["winner"] == "B")
    print(f"\n🏆 Pairwise Comparison:")
    print(f"   New variant wins {b_wins}/{len(pairwise_results)} head-to-head matchups")

print(f"\n💡 Key Insight:")
if overall_v2 > overall_v1:
    print(f"   New prompt v2 (strict policy-adherent) shows {overall_v2 - overall_v1:.2f} point improvement.")
else:
    print(f"   Baseline performs better. Consider refining v2 prompt.")

print("\n" + "=" * 70)

